<?php
namespace App\Http\Controllers;
use App\Models\InternshipParticipant;
use App\Models\InternshipAttendance;
use App\Exports\InternshipAttendanceExport;
use App\Exports\InternshipProgramRecapExport;
use App\Services\InternshipCertificateService;
use App\Models\InternshipProgram;
use App\Models\ElectronicSignatureRequest as SignatureRequest;
use App\Models\User;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Str;
use Illuminate\Support\Facades\Storage;
use Maatwebsite\Excel\Facades\Excel;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Validation\Rule;
class InternshipController extends Controller {
 private function guard():void {abort_unless(Auth::user()->role==='superadmin',403);}
 private function authorizeProgram(InternshipProgram $program):void {$this->guard();if(Auth::user()->role!=='superadmin')abort_unless($program->bidang===Auth::user()->bidang,403);}
 public function index(Request $request){$this->guard();$q=InternshipProgram::withCount(['participants','participants as pending_count'=>fn($x)=>$x->where('status','pending')]);if(Auth::user()->role!=='superadmin')$q->where('bidang',Auth::user()->bidang);$programs=$q->when($request->q,fn($x,$v)=>$x->where('title','like','%'.$v.'%'))->latest()->paginate(12)->withQueryString();return view('internships.admin.index',compact('programs'));}
 public function store(Request $request){$this->guard();$data=$this->validateProgram($request);if(Auth::user()->role!=='superadmin')$data['bidang']=Auth::user()->bidang;$data+=['public_token'=>(string)Str::uuid(),'created_by'=>Auth::id()];$program=InternshipProgram::create($data);return redirect()->route('internships.show',$program)->with('success','Program magang berhasil dibuat.');}
 public function show(Request $request,InternshipProgram $program){$this->authorizeProgram($program);$filters=$request->validate(['from'=>'nullable|date','to'=>'nullable|date|after_or_equal:from']);$from=$filters['from']??now('Asia/Jakarta')->startOfYear()->toDateString();$to=$filters['to']??now('Asia/Jakarta')->endOfYear()->toDateString();$program->loadCount('participants');$participants=$program->participants()->with('user')->withCount('attendances')->latest()->paginate(20,['*'],'participants_page')->withQueryString();$recapParticipants=$this->programRecapQuery($program,$from,$to)->orderBy('name')->paginate(25,['*'],'recap_page')->withQueryString();$attendanceBase=InternshipAttendance::whereHas('participant',fn($q)=>$q->where('internship_program_id',$program->id))->whereBetween('attendance_date',[$from,$to]);$recapSummary=['participants'=>$program->participants()->where('status','approved')->count(),'present'=>(clone $attendanceBase)->whereIn('status',['present','permission','sick'])->count(),'late_days'=>(clone $attendanceBase)->where('late_minutes','>',0)->count(),'late_minutes'=>(int)(clone $attendanceBase)->sum('late_minutes'),'permission'=>(clone $attendanceBase)->where('status','permission')->count(),'sick'=>(clone $attendanceBase)->where('status','sick')->count()];$tteUsers=User::where('role','penandatangan')->whereNotNull('nip_nik')->where('nip_nik','!=','')->orderBy('name')->get(['id','name','nip_nik','jabatan']);$latestTteRequest=SignatureRequest::where('source_type','training_certificates')->where('external_reference','internship-program:'.$program->id)->latest()->first();$absenceRequests=InternshipAttendance::with('participant')->whereHas('participant',fn($q)=>$q->where('internship_program_id',$program->id))->whereIn('status',['permission','sick'])->latest('attendance_date')->take(30)->get();return view('internships.admin.show',compact('program','participants','absenceRequests','recapParticipants','recapSummary','from','to','tteUsers','latestTteRequest'));}
 private function programRecapQuery(InternshipProgram $program,string $from,string $to){$period=fn($q)=>$q->whereBetween('attendance_date',[$from,$to]);return $program->participants()->where('status','approved')->withCount(['attendances as recap_present_count'=>fn($q)=>$period($q)->whereIn('status',['present','permission','sick']),'attendances as recap_late_count'=>fn($q)=>$period($q)->where('late_minutes','>',0),'attendances as recap_permission_count'=>fn($q)=>$period($q)->where('status','permission'),'attendances as recap_sick_count'=>fn($q)=>$period($q)->where('status','sick'),'attendances as recap_missing_checkout_count'=>fn($q)=>$period($q)->where('status','present')->whereNull('check_out_at')])->withSum(['attendances as recap_late_minutes'=>fn($q)=>$period($q)],'late_minutes');}
 public function exportProgramRecap(Request $request,InternshipProgram $program){$this->authorizeProgram($program);$filters=$request->validate(['from'=>'nullable|date','to'=>'nullable|date|after_or_equal:from']);$from=$filters['from']??now('Asia/Jakarta')->startOfYear()->toDateString();$to=$filters['to']??now('Asia/Jakarta')->endOfYear()->toDateString();$rows=$this->programRecapQuery($program,$from,$to)->orderBy('name')->get();return Excel::download(new InternshipProgramRecapExport($rows,$from,$to),'rekap-magang-'.Str::slug($program->title).'-'.$from.'-'.$to.'.xlsx');}
 public function update(Request $request,InternshipProgram $program){$this->authorizeProgram($program);$data=$this->validateProgram($request);if(Auth::user()->role!=='superadmin')$data['bidang']=Auth::user()->bidang;$program->update($data);return back()->with('success','Pengaturan program berhasil disimpan.');}
 public function approve(Request $request,InternshipParticipant $participant){$this->authorizeProgram($participant->program);$request->validate(['review_note'=>'nullable|string|max:1000']);$participant->update(['status'=>'approved','review_note'=>$request->review_note,'reviewed_by'=>Auth::id(),'reviewed_at'=>now()]);$participant->user?->update(['user_type_status'=>'approved']);return back()->with('success','Pendaftaran '.$participant->name.' disetujui dan akunnya telah aktif.');}
 public function reject(Request $request,InternshipParticipant $participant){$this->authorizeProgram($participant->program);$data=$request->validate(['review_note'=>'required|string|max:1000']);$participant->update(['status'=>'rejected','review_note'=>$data['review_note'],'reviewed_by'=>Auth::id(),'reviewed_at'=>now()]);$participant->user?->update(['user_type_status'=>'rejected']);return back()->with('success','Pendaftaran ditolak.');}
 public function updateParticipantGrade(Request $request,InternshipParticipant $participant,InternshipCertificateService $service){$this->authorizeProgram($participant->program);$data=$request->validate(['final_grade'=>'required|in:Sangat Baik,Baik,Cukup,Kurang']);$recommended=$service->recommendedGrade($participant);$participant->update(['recommended_grade'=>$recommended,'final_grade'=>$data['final_grade']]);return back()->with('success','Predikat akhir '.$participant->name.' berhasil ditetapkan.');}
 public function updateCertificateSettings(Request $request,InternshipProgram $program,InternshipCertificateService $service){$this->authorizeProgram($program);$data=$request->validate(['certificate_template'=>'nullable|file|mimes:docx|max:10240','certificate_number_format'=>'required|string|max:255','certificate_start_sequence'=>'required|integer|min:1','certificate_issued_at'=>'required|date','certificate_signer_id'=>['required',Rule::exists('users','id')->where('role','penandatangan')],'certificate_reviewer_ids'=>'nullable|array|max:10','certificate_reviewer_ids.*'=>['integer','distinct',Rule::exists('users','id')->where('role','penandatangan'),Rule::notIn([(int)$request->input('certificate_signer_id')])]]);if(!str_contains($data['certificate_number_format'],'{X}'))return back()->withErrors(['certificate_number_format'=>'Format nomor wajib memuat {X} sebagai nomor urut.'])->withInput();if($request->hasFile('certificate_template')){$service->validateTemplate($request->file('certificate_template')->getRealPath());if($program->certificate_template_path)Storage::disk('local')->delete($program->certificate_template_path);$data['certificate_template_path']=$request->file('certificate_template')->store('internships/certificate-templates','local');}unset($data['certificate_template']);$program->update($data);return back()->with('success','Pengaturan sertifikat magang berhasil disimpan.');}
 public function downloadCertificateTemplate(InternshipCertificateService $service){$path=tempnam(sys_get_temp_dir(),'intern-template-').'.docx';$service->createSampleTemplate($path);return response()->download($path,'template-sertifikat-magang.docx')->deleteFileAfterSend(true);}
 public function generateCertificates(InternshipProgram $program,InternshipCertificateService $service){$this->authorizeProgram($program);if(!$program->certificate_template_path||!Storage::disk('local')->exists($program->certificate_template_path))return back()->withErrors(['certificate_template'=>'Unggah template sertifikat terlebih dahulu.']);if(!$program->certificate_signer_id)return back()->withErrors(['certificate_signer_id'=>'Pilih penandatangan akhir terlebih dahulu.']);if(SignatureRequest::where('source_type','training_certificates')->where('external_reference','internship-program:'.$program->id)->where('status','!=','completed')->exists())return back()->withErrors(['certificate'=>'Masih ada bundel sertifikat magang dalam proses TTE. Selesaikan dahulu sebelum generate ulang.']);$participants=$program->participants()->where('status','approved')->whereDate('end_date','<',today('Asia/Jakarta'))->orderBy('name')->get();if($participants->isEmpty())return back()->withErrors(['certificate'=>'Belum ada peserta yang masa magangnya selesai.']);foreach($participants as $index=>$participant){$recommended=$service->recommendedGrade($participant);$final=$participant->final_grade?:$recommended;$number=str_replace('{X}',(string)($program->certificate_start_sequence+$index),$program->certificate_number_format);$relative='internships/certificates/'.$program->id.'/generated/'.$participant->id.'.pdf';$participant->setAttribute('recommended_grade',$recommended);$participant->setAttribute('final_grade',$final);$service->render($program,$participant,$number,Storage::disk('local')->path($relative));$participant->update(['recommended_grade'=>$recommended,'final_grade'=>$final,'certificate_number'=>$number,'certificate_generated_file_path'=>$relative,'certificate_file_path'=>null,'certificate_generated_at'=>now(),'certificate_sent_at'=>null,'certificate_sent_by'=>null,'certificate_downloaded_at'=>null]);}$signatureRequest=DB::transaction(function()use($program,$participants){$signature=SignatureRequest::create(['uuid'=>(string)Str::uuid(),'title'=>'Sertifikat Magang/PKL - '.$program->title,'description'=>'Penandatanganan '.$participants->count().' sertifikat peserta magang.','bidang'=>$program->bidang,'source_type'=>'training_certificates','training_id'=>null,'external_reference'=>'internship-program:'.$program->id,'status'=>'in_progress','created_by'=>Auth::id()]);$actors=collect($program->certificate_reviewer_ids??[])->values()->map(fn($id,$index)=>$signature->actors()->create(['user_id'=>$id,'role'=>'reviewer','sequence'=>$index+1]));$actors->push($signature->actors()->create(['user_id'=>$program->certificate_signer_id,'role'=>'signer','sequence'=>$actors->count()+1]));foreach($participants as $participant){$document=$signature->documents()->create(['internship_participant_id'=>$participant->id,'original_name'=>Str::slug($participant->student_number?:$participant->name).'.pdf','original_path'=>$participant->certificate_generated_file_path,'current_path'=>$participant->certificate_generated_file_path,'file_size'=>Storage::disk('local')->size($participant->certificate_generated_file_path),'status'=>'waiting']);foreach($actors as $index=>$actor)$document->actions()->create(['electronic_signature_actor_id'=>$actor->id,'status'=>$index===0?'pending':'waiting']);}return $signature;});return redirect()->route('electronic-signatures.show',$signatureRequest)->with('success',$participants->count().' sertifikat berhasil dibuat dan otomatis masuk antrean TTE.');}
 public function sendReadyCertificates(InternshipProgram $program){$this->authorizeProgram($program);$participants=$program->participants()->whereNotNull('certificate_file_path')->whereNull('certificate_sent_at')->get()->filter(fn($participant)=>Storage::disk('local')->exists($participant->certificate_file_path));if($participants->isEmpty())return back()->withErrors(['certificate'=>'Belum ada hasil TTE yang siap dikirim.']);InternshipParticipant::whereIn('id',$participants->pluck('id'))->update(['certificate_sent_at'=>now(),'certificate_sent_by'=>Auth::id(),'certificate_downloaded_at'=>null]);return back()->with('success',$participants->count().' sertifikat hasil TTE berhasil dikirim ke akun peserta.');}
 public function adminMarkPresent(Request $request,InternshipParticipant $participant){$this->authorizeProgram($participant->program);abort_unless($participant->status==='approved',422,'Hanya peserta aktif yang dapat diabsenkan.');$data=$request->validate(['attendance_date'=>'required|date','check_in_time'=>'required|date_format:H:i','note'=>'nullable|string|max:1000']);$date=$data['attendance_date'];if($date<$participant->start_date->toDateString()||$date>$participant->end_date->toDateString())return back()->withErrors(['attendance_date'=>'Tanggal presensi harus berada dalam periode magang peserta.'])->withInput();if($participant->attendances()->whereDate('attendance_date',$date)->exists())return back()->withErrors(['attendance_date'=>'Presensi atau status izin/sakit pada tanggal tersebut sudah tercatat.'])->withInput();$participant->attendances()->create(['attendance_date'=>$date,'status'=>'present','check_in_at'=>\Carbon\Carbon::createFromFormat('Y-m-d H:i',$date.' '.$data['check_in_time'],'Asia/Jakarta'),'late_minutes'=>0,'note'=>'Dicatat oleh admin'.(!empty($data['note'])?': '.$data['note']:'.'),'review_status'=>'not_required','reviewed_by'=>Auth::id(),'reviewed_at'=>now()]);return back()->with('success','Kehadiran '.$participant->name.' berhasil dicatat oleh admin tanpa keterlambatan.');}
 public function participantAttendance(Request $request,InternshipParticipant $participant){$this->authorizeProgram($participant->program);$filters=$request->validate(['month'=>'nullable|date_format:Y-m','status'=>'nullable|in:present,permission,sick,absent']);$month=$filters['month']??null;$status=$filters['status']??null;$query=$participant->attendances()->when($month,function($q,$value){[$year,$monthNumber]=explode('-',$value);$q->whereYear('attendance_date',$year)->whereMonth('attendance_date',$monthNumber);})->when($status,fn($q,$value)=>$q->where('status',$value));$attendances=(clone $query)->latest('attendance_date')->paginate(20)->withQueryString();$base=$participant->attendances();$stats=['present'=>(clone $base)->whereIn('status',['present','permission','sick'])->count(),'late_days'=>(clone $base)->where('late_minutes','>',0)->count(),'late_minutes'=>(int)(clone $base)->sum('late_minutes'),'permission'=>(clone $base)->where('status','permission')->count(),'sick'=>(clone $base)->where('status','sick')->count(),'missing_checkout'=>(clone $base)->where('status','present')->whereNull('check_out_at')->count()];return view('internships.admin.participant-attendance',compact('participant','attendances','stats','month','status'));}
 public function exportParticipantAttendance(Request $request,InternshipParticipant $participant){$this->authorizeProgram($participant->program);$filters=$request->validate(['month'=>'nullable|date_format:Y-m','status'=>'nullable|in:present,permission,sick,absent']);$query=$participant->attendances()->when($filters['month']??null,function($q,$value){[$year,$monthNumber]=explode('-',$value);$q->whereYear('attendance_date',$year)->whereMonth('attendance_date',$monthNumber);})->when($filters['status']??null,fn($q,$value)=>$q->where('status',$value));$rows=$query->oldest('attendance_date')->get();$safeName=Str::slug($participant->name.'-'.$participant->student_number);return Excel::download(new InternshipAttendanceExport($participant,$rows),'rekap-presensi-'.$safeName.'.xlsx');}
 public function updateParticipant(Request $request,InternshipParticipant $participant){$this->authorizeProgram($participant->program);$data=$request->validate(['name'=>'required|string|max:255','student_number'=>['required','string','max:100',Rule::unique('internship_participants')->where(fn($q)=>$q->where('internship_program_id',$participant->internship_program_id))->ignore($participant->id),Rule::unique('users','username')->ignore($participant->user_id)],'major'=>'required|string|max:255','institution'=>'required|string|max:255','placement_unit'=>'required|string|max:255','start_date'=>'required|date','end_date'=>'required|date|after_or_equal:start_date','email'=>'required|email|max:255']);DB::transaction(function()use($participant,$data){$participant->update($data);$participant->user?->update(['name'=>$data['name'],'username'=>trim($data['student_number']),'bidang'=>$data['placement_unit']]);});return back()->with('success','Data '.$participant->name.' berhasil diperbarui. Username login mengikuti NIS/NIM terbaru.');}
 public function resetParticipantPassword(Request $request,InternshipParticipant $participant){$this->authorizeProgram($participant->program);$data=$request->validate(['password'=>'required|string|min:8|confirmed']);abort_unless($participant->user,422,'Akun peserta tidak ditemukan.');$participant->user->update(['password'=>Hash::make($data['password'])]);return back()->with('success','Password akun '.$participant->name.' berhasil diperbarui.');}
 public function downloadEvidence(InternshipAttendance $attendance){$this->authorizeProgram($attendance->participant->program);abort_unless($attendance->evidence_path&&Storage::disk('local')->exists($attendance->evidence_path),404);return Storage::disk('local')->download($attendance->evidence_path);}
 private function validateProgram(Request $request):array{return $request->validate(['title'=>'required|string|max:255','bidang'=>'nullable|string|max:255','description'=>'nullable|string|max:3000','registration_opens_at'=>'nullable|date','registration_closes_at'=>'nullable|date|after_or_equal:registration_opens_at','check_in_opens_at'=>'required|date_format:H:i','late_after'=>'required|date_format:H:i|after:check_in_opens_at','check_out_opens_at'=>'required|date_format:H:i|after:late_after','status'=>['required',Rule::in(['draft','open','closed','archived'])]]);}
}